package com.bheemnagartimes.news.service;
import com.bheemnagartimes.news.model.NewsArticle;import org.springframework.stereotype.Service;import org.springframework.http.MediaType;import org.springframework.web.client.RestClient;import com.fasterxml.jackson.databind.*;import com.fasterxml.jackson.databind.node.*;import org.springframework.beans.factory.annotation.Value;import java.util.regex.Pattern;
@Service public class ArticleGeneratorService{private final ObjectMapper mapper;private final RestClient client;private final boolean aiEnabled;private final String apiKey;private final String model;public ArticleGeneratorService(ObjectMapper mapper,@Value("${ai.enabled:false}") boolean aiEnabled,@Value("${ai.base-url:https://api.openai.com/v1}") String baseUrl,@Value("${ai.api-key:}") String apiKey,@Value("${ai.model:gpt-4o-mini}") String model){this.mapper=mapper;this.aiEnabled=aiEnabled&&apiKey!=null&&!apiKey.isBlank();this.apiKey=apiKey;this.model=model;this.client=RestClient.builder().baseUrl(baseUrl).build();}public NewsArticle generate(String raw,String date,String location,String section){if(aiEnabled)try{return generateWithAi(raw,date,location,section);}catch(Exception ignored){}String text=raw.trim().replace("\r","");NewsArticle a=new NewsArticle();a.setSection(section==null||section.isBlank()?detectSection(text):section);a.setHeadline(headline(text));String first=text.split("(?<=[।!?])\\s+")[0];a.setSubheadline(first.length()>110?first.substring(0,110)+"…":first);a.setStrapline("मुख्य घटनाक्रम, संबंधित पक्षों की प्रतिक्रिया और आगे की प्रक्रिया पर नजर");a.setDateline((location==null||location.isBlank()?"भीमनगर":location)+", "+(date==null||date.isBlank()?"22 सितंबर 2026":date)+" |");a.setBody(paragraphs(text));a.setSecondaryHeading("मामले की मुख्य बातें");a.setSecondaryBody("उपलब्ध जानकारी के अनुसार संबंधित विभाग और पक्ष मामले पर आगे की प्रक्रिया तय करेंगे। आधिकारिक आदेश या अंतिम निर्णय आने पर जानकारी अपडेट की जाएगी।");a.setSidebarHeading("त्वरित दृष्टि");a.setSidebarBody("अंतिम प्रकाशन से पहले नाम, तारीख, आंकड़े और आधिकारिक स्रोतों का सत्यापन करें।");String q=quote(text);a.setQuote(q);a.setQuoteAttribution(q.isBlank()?"":"स्रोत में दर्ज कथन");return a;}private NewsArticle generateWithAi(String raw,String date,String location,String section)throws Exception{String prompt="Rewrite this raw Hindi news for a local newspaper. Preserve all facts, names, dates, numbers and quotations. Do not invent information. Return only JSON with keys section,headline,subheadline,strapline,body,secondaryHeading,secondaryBody,quote,quoteAttribution,sidebarHeading,sidebarBody. Body must contain 3-5 short paragraphs separated by blank lines. Raw news:\\n"+raw;ObjectNode payload=mapper.createObjectNode();payload.put("model",model);payload.put("temperature",0.2);ArrayNode messages=payload.putArray("messages");messages.addObject().put("role","system").put("content","Return valid JSON only. No markdown.");messages.addObject().put("role","user").put("content",prompt);String response=client.post().uri("/chat/completions").header("Authorization","Bearer "+apiKey).contentType(MediaType.APPLICATION_JSON).body(payload).retrieve().body(String.class);JsonNode j=mapper.readTree(response).path("choices").path(0).path("message").path("content");JsonNode n=mapper.readTree(j.asText().replaceFirst("^\\\\s*```json\\\\s*","").replaceFirst("\\\\s*```\\\\s*$","").trim());NewsArticle a=new NewsArticle();a.setSection(value(n,"section",section==null||section.isBlank()?detectSection(raw):section));a.setHeadline(value(n,"headline",headline(raw)));a.setSubheadline(value(n,"subheadline",raw.split("(?<=[।!?])\\\\s+")[0]));a.setStrapline(value(n,"strapline","मुख्य घटनाक्रम, संबंधित पक्षों की प्रतिक्रिया और आगे की प्रक्रिया पर नजर"));a.setBody(value(n,"body",raw.trim()));a.setSecondaryHeading(value(n,"secondaryHeading","मामले की मुख्य बातें"));a.setSecondaryBody(value(n,"secondaryBody","संबंधित पक्षों और विभागों की अगली कार्रवाई पर नजर बनी हुई है।"));a.setQuote(value(n,"quote",""));a.setQuoteAttribution(value(n,"quoteAttribution",""));a.setSidebarHeading(value(n,"sidebarHeading","त्वरित दृष्टि"));a.setSidebarBody(value(n,"sidebarBody","अंतिम प्रकाशन से पहले तथ्यों का सत्यापन करें।"));a.setDateline((location==null||location.isBlank()?"भीमनगर":location)+", "+(date==null||date.isBlank()?"22 सितंबर 2026":date)+" |");return a;}private String value(JsonNode n,String k,String f){String v=n.path(k).asText("").trim();return v.isBlank()?f:v;}private String headline(String t){if(has(t,"cctv","सीसीटीवी","कैमरा"))return"मेडिकल स्टोर पर सीसीटीवी लगाने की तैयारी?";if(has(t,"skill","स्किल","कौशल"))return"युवाओं के लिए हुनर दिखाने का बड़ा मौका";if(has(t,"सड़क","हाईवे","एनएच"))return"सड़क से जुड़े प्रस्ताव पर बढ़ी निगरानी";if(has(t,"बिजली","विद्युत"))return"बिजली व्यवस्था को लेकर प्रशासन से उम्मीदें बढ़ीं";String s=clean(t);String first=firstSentence(s);if(first.length()>96)first=first.substring(0,96).replaceAll("\\s+[^\\s]*$","").trim()+"…";return first.isBlank()?"स्थानीय समाचार":first;}private String clean(String t){return t.replaceAll("(?m)^\\s*[*#>]+\\s*","").replaceAll("\\*+","").replaceAll("(?i)^(ब्रेकिंग|ताजा खबर|बड़ी खबर)[:：-]?\\s*","").replaceAll("[\\r\\n]+"," ").replaceAll("\\s{2,}"," ").trim();}private String firstSentence(String t){String[] s=t.split("(?<=[।!?])\\s+");return s.length==0?t:s[0].trim();}private boolean has(String t,String...xs){String l=t.toLowerCase();for(String x:xs)if(l.contains(x.toLowerCase()))return true;return false;}private String detectSection(String t){if(has(t,"सरकार","मंत्रालय","प्रस्ताव","नियम"))return"जनहित में बड़ा फैसला";if(has(t,"युवा","स्किल","कौशल","प्रतियोगिता"))return"युवा अवसर";if(has(t,"स्वास्थ्य","अस्पताल","दवा","मेडिकल"))return"स्वास्थ्य";return"स्थानीय समाचार";}private String paragraphs(String t){String n=t.replaceAll("\\n{3,}","\\n\\n").trim();if(n.contains("\\n\\n"))return n;String[] s=n.split("(?<=[।!?])\\s+");StringBuilder b=new StringBuilder();int c=0;for(String x:s){if(x.isBlank())continue;if(b.length()>0)b.append("\\n\\n");b.append(x.trim());if(++c>=5)break;}return b.toString();}private String quote(String t){var m=Pattern.compile("[“\\\"]([^”\\\"]{20,220})[”\\\"]").matcher(t);return m.find()?m.group(1):"";}}